// A person's edits to their own items: trash, restore, deleting for good, favorites and albums.
// Each write is limited to the owner's items (or, for favorites and albums, to items the viewer
// can see through the gate).
// Moves the owner's items to the trash, with their Live Photo clips and the RAW of a RAW+JPEG pair
// they top (they went in together, so they come back together). Other stacks keep the rest: they
// get a new top (ReplaceTrashedCovers).
func (q *Queries) TrashAssets(ctx context.Context, arg TrashAssetsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, trashAssets, arg.Owner, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trashedBefore = `-- name: TrashedBefore :many
SELECT a.id FROM assets a
WHERE a.trashed_at < $1::timestamptz AND a.purged_at IS NULL
ORDER BY a.trashed_at
LIMIT $2
`

type TrashedBeforeParams struct {
	Before time.Time
	Lim    int32
}

// Everyone's items trashed before a time and not deleted yet (the 30-day clean-up).
func (q *Queries) TrashedBefore(ctx context.Context, arg TrashedBeforeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, trashedBefore, arg.Before, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trashedOf = `-- name: TrashedOf :many
WITH picked AS (
    SELECT a.id, a.trashed_at FROM assets a
    WHERE a.owner_id = $1::uuid AND a.trashed_at IS NOT NULL AND a.purged_at IS NULL
      AND (a.visibility = 'vault') = $2::boolean
      AND (cardinality($3::uuid[]) = 0 OR a.id = ANY($3::uuid[]))
)
SELECT picked.id FROM picked
UNION SELECT m.id FROM assets m JOIN picked ON m.motion_of = picked.id WHERE m.trashed_at IS NOT NULL AND m.purged_at IS NULL
UNION SELECT sa.asset_id FROM stacks st JOIN stack_assets sa ON sa.stack_id = st.id JOIN picked ON st.cover_asset_id = picked.id
      JOIN assets x ON x.id = sa.asset_id
      WHERE st.state = 'confirmed' AND st.kind = 'raw_jpeg' AND x.trashed_at IS NOT NULL AND x.purged_at IS NULL
`

type TrashedOfParams struct {
	Owner uuid.UUID
	Vault bool
	Ids   []uuid.UUID
}

// Items in the owner's trash to delete for good: the ones given (with what went in with them), or
// the whole trash when none are given. The vault's trash is apart: only its own Delete reaches it.
func (q *Queries) TrashedOf(ctx context.Context, arg TrashedOfParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, trashedOf, arg.Owner, arg.Vault, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAlbum = `-- name: UpdateAlbum :execrows
UPDATE albums SET title = coalesce($1, title), description = coalesce($2, description),
    query = CASE WHEN kind = 'smart' THEN coalesce($3::jsonb, query) ELSE query END, updated_at = now()
WHERE id = $4 AND owner_id = $5::uuid
`

type UpdateAlbumParams struct {
	Title       pgtype.Text
	Description pgtype.Text
	Query       []byte
	ID          uuid.UUID
	Owner       uuid.UUID
}

// A new title, description or (for a smart album) rules; anything left out stays.
func (q *Queries) UpdateAlbum(ctx context.Context, arg UpdateAlbumParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAlbum,
		arg.Title,
		arg.Description,
		arg.Query,
		arg.ID,
		arg.Owner,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const writableFiles = `-- name: WritableFiles :many
SELECT f.id, f.asset_id, l.root_path, f.rel_path
FROM files f JOIN libraries l ON l.id = f.library_id
WHERE f.asset_id = ANY($1::uuid[]) AND l.kind = 'managed' AND NOT l.read_only AND f.state = 'present'
`

type WritableFilesRow struct {
	ID       uuid.UUID
	AssetID  uuid.NullUUID
	RootPath string
	RelPath  string
}

// The files of these items that Photostead may delete: only in writable, managed libraries.
func (q *Queries) WritableFiles(ctx context.Context, ids []uuid.UUID) ([]WritableFilesRow, error) {
	rows, err := q.db.Query(ctx, writableFiles, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WritableFilesRow{}
	for rows.Next() {
		var i WritableFilesRow
		if err := rows.Scan(
			&i.ID,
			&i.AssetID,
			&i.RootPath,
			&i.RelPath,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
